    [/^(🏆 You win the match|😢 The computer wins the match) (\d+) - (\d+)$/, (m, r, a, b) => `${r.startsWith("🏆") ? "🏆 ניצחתם במשחק" : "😢 המחשב ניצח במשחק"} ${a} - ${b}`]
